<?php
require_once __DIR__.'/../includes/functions.php'; require_once __DIR__.'/../includes/csrf.php';
$d=json_input(); require_csrf($d['csrf_token']??null); if(($d['action']??'')!=='submit')json_response(['ok'=>false,'message'=>'Unsupported action'],400);
$token=trim($d['survey_token']??'');$s=db()->prepare("SELECT * FROM surveys WHERE public_token=? AND status='active' AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW())");$s->execute([$token]);$survey=$s->fetch();if(!$survey)json_response(['ok'=>false,'message'=>'This survey is not currently accepting responses.'],404);
$invitationId=null;$inviteToken=trim($d['invitation_token']??'');if($inviteToken){$i=db()->prepare('SELECT * FROM survey_invitations WHERE invite_token=? AND survey_id=?');$i->execute([$inviteToken,$survey['id']]);$inv=$i->fetch();if(!$inv)json_response(['ok'=>false,'message'=>'Invalid survey invitation.'],422);if($inv['completed_at'])json_response(['ok'=>false,'message'=>'This invitation has already been used.'],409);$invitationId=$inv['id'];}
$q=db()->prepare('SELECT * FROM survey_questions WHERE survey_id=? ORDER BY sort_order');$q->execute([$survey['id']]);$questions=$q->fetchAll();$answers=$d['answers']??[];foreach($questions as $question){if($question['required'] && (!isset($answers[$question['id']]) || $answers[$question['id']]==='' || $answers[$question['id']]===[]))json_response(['ok'=>false,'message'=>'Please answer all required questions.'],422);}
$pdo=db();$pdo->beginTransaction();try{$r=$pdo->prepare('INSERT INTO survey_responses(survey_id,invitation_id,response_token,submitted_at) VALUES(?,?,?,NOW())');$r->execute([$survey['id'],$invitationId,uuid_token(20)]);$rid=(int)$pdo->lastInsertId();foreach($questions as $question){$val=$answers[$question['id']]??null;if($val===null||$val===''||$val===[])continue;$a=$pdo->prepare('INSERT INTO survey_answers(response_id,question_id,answer_text) VALUES(?,?,?)');$text=is_array($val)?null:(string)$val;$a->execute([$rid,$question['id'],$text]);$aid=(int)$pdo->lastInsertId();if(is_array($val) || in_array($question['question_type'],['single','dropdown'],true)){foreach((array)$val as $oid){if(!ctype_digit((string)$oid))continue;$chk=$pdo->prepare('SELECT id FROM question_options WHERE id=? AND question_id=?');$chk->execute([(int)$oid,$question['id']]);if($chk->fetchColumn()){$sel=$pdo->prepare('INSERT INTO answer_selections(answer_id,option_id) VALUES(?,?)');$sel->execute([$aid,(int)$oid]);}}}}if($invitationId)$pdo->prepare('UPDATE survey_invitations SET completed_at=NOW() WHERE id=?')->execute([$invitationId]);$pdo->commit();json_response(['ok'=>true]);}catch(Throwable $e){$pdo->rollBack();json_response(['ok'=>false,'message'=>'Could not save response.'],500);}
